1	import { useEffect, useMemo, useState } from 'react';
2	import {
3	  Loader2,
4	  Save,
5	  ArrowLeft,
6	  CheckSquare,
7	  XSquare,
8	  Search,
9	} from 'lucide-react';
10	import { Button } from '@/shared/ui/button';
11	import { Checkbox } from '@/shared/ui/checkbox';
12	import { Input } from '@/shared/ui/input';
13	import {
14	  Select,
15	  SelectContent,
16	  SelectItem,
17	  SelectTrigger,
18	  SelectValue,
19	} from '@/shared/ui/select';
20	import { supabase } from '@/integrations/supabase/client';
21	import { toast } from '@/shared/hooks/use-toast';
22	import { handleError } from '@/shared/lib/error-handler';
23	
24	/**
25	 * Matrix de Visibilidade Produto × Loja.
26	 *
27	 * Admin-only. Carrega produtos ativos de `produtos_master` e lojas ativas,
28	 * cruza com `produto_loja_visibility` e renderiza um grid de checkboxes.
29	 * Controla quais produtos aparecem na aba Contagem de cada loja.
30	 *
31	 * Recuperado do commit 41a96c4 (perdido no refactor FSD). A view
32	 * `vw_produtos_estoque_lojas` que alimenta a contagem JÁ faz INNER JOIN
33	 * com esta tabela, então as mudanças refletem direto na contagem.
34	 */
35	
36	interface ProductVisibilityMatrixProps {
37	  onBack: () => void;
38	}
39	
40	interface Produto {
41	  id: number;
42	  nome: string;
43	  setor: string;
44	  codigo_interno: number | null;
45	}
46	
47	interface Loja {
48	  id: number;
49	  nome: string;
50	}
51	
52	const visKey = (prodId: number, lojaId: number) => `${prodId}_${lojaId}`;
53	
54	const setorEmoji = (nome: string): string => {
55	  const n = (nome || '').toLowerCase();
56	  if (n.includes('câmara fria') || n.includes('camara fria')) return '❄️';
57	  if (n === 'insumos' || n.includes('estoque insumos')) return '🥄';
58	  if (n === 'mercearia') return '🛒';
59	  if (n === 'embalagens') return '📦';
60	  if (n === 'limpeza') return '🧼';
61	  if (n === 'natal') return '🎅';
62	  if (n === 'todos') return '🌎';
63	  return '🏷️';
64	};
65	
66	export function ProductVisibilityMatrix({
67	  onBack,
68	}: ProductVisibilityMatrixProps) {
69	  const [loading, setLoading] = useState(false);
70	  const [saving, setSaving] = useState(false);
71	  const [allProducts, setAllProducts] = useState<Produto[]>([]);
72	  const [lojas, setLojas] = useState<Loja[]>([]);
73	  const [officialSetoresList, setOfficialSetoresList] = useState<string[]>([]);
74	  const [visibility, setVisibility] = useState<Record<string, boolean>>({});
75	  const [initialVisibility, setInitialVisibility] = useState<
76	    Record<string, boolean>
77	  >({});
78	  const [searchTerm, setSearchTerm] = useState('');
79	  const [setorSelecionado, setSetorSelecionado] = useState('Todos');
80	
81	  useEffect(() => {
82	    loadData();
83	    // eslint-disable-next-line react-hooks/exhaustive-deps
84	  }, []);
85	
86	  const loadData = async () => {
87	    setLoading(true);
88	    try {
89	      // 1. Setores oficiais (fonte da verdade — mesma tabela usada na Contagem)
90	      const { data: setoresData, error: setoresError } = await supabase
91	        .from('setores')
92	        .select('nome, ativo')
93	        .eq('ativo', true)
94	        .order('nome');
95	      if (setoresError) throw setoresError;
96	      const officialSetores = (setoresData || [])
97	        .map((s: any) => s.nome as string)
98	        .filter((n: string) => !!n && n.trim() !== '');
99	      // Map normalizado (UPPERCASE + trim) → nome canônico para match case-insensitive
100	      const officialMap = new Map<string, string>();
101	      officialSetores.forEach((n) => {
102	        officialMap.set(n.trim().toUpperCase(), n);
103	      });
104	
105	      // 2. Produtos ativos
106	      const { data: productsData, error: productsError } = await supabase
107	        .from('produtos_master')
108	        .select('id, nome, setor, codigo_interno, ativo')
109	        .eq('ativo', true)
110	        .order('nome');
111	      if (productsError) throw productsError;
112	
113	      // 3. Lojas ativas
114	      const { data: lojasData, error: lojasError } = await supabase
115	        .from('lojas')
116	        .select('id, nome')
117	        .or('ativo.eq.true,ativo.is.null')
118	        .order('id');
119	      if (lojasError) throw lojasError;
120	
121	      // 4. Visibilidade (paginado — pode ultrapassar 1000 linhas)
122	      const visAll: {
123	        produto_master_id: number;
124	        loja_id: number;
125	        ativo: boolean;
126	      }[] = [];
127	      let offset = 0;
128	      const PAGE = 1000;
129	      while (true) {
130	        const { data: batch, error: batchErr } = await supabase
131	          .from('produto_loja_visibility' as any)
132	          .select('produto_master_id, loja_id, ativo')
133	          .range(offset, offset + PAGE - 1);
134	        if (batchErr) throw batchErr;
135	        if (!batch || batch.length === 0) break;
136	        visAll.push(...(batch as any));
137	        if (batch.length < PAGE) break;
138	        offset += PAGE;
139	      }
140	
141	      // Normaliza setor de cada produto pro nome canônico (case-insensitive).
142	      // Produtos com setor inválido (NULL, "Todos", etc) são descartados.
143	      const prods: Produto[] = (productsData || [])
144	        .map((p: any) => {
145	          const raw = (p.setor || '').trim();
146	          const canonical = raw ? officialMap.get(raw.toUpperCase()) : undefined;
147	          if (!canonical) return null;
148	          return {
149	            id: p.id,
150	            nome: p.nome,
151	            setor: canonical,
152	            codigo_interno: p.codigo_interno,
153	          } as Produto;
154	        })
155	        .filter((p: Produto | null): p is Produto => p !== null);
156	
157	      setAllProducts(prods);
158	      setOfficialSetoresList(officialSetores);
159	      setLojas(
160	        (lojasData || []).map((l: any) => ({ id: l.id, nome: l.nome })),
161	      );
162	
163	      const visMap: Record<string, boolean> = {};
164	      visAll.forEach((v) => {
165	        visMap[visKey(v.produto_master_id, v.loja_id)] = v.ativo;
166	      });
167	      setVisibility(visMap);
168	      setInitialVisibility({ ...visMap });
169	    } catch (error) {
170	      handleError(error, {
171	        domain: 'produtos',
172	        operation: 'loadVisibilityMatrix',
173	        showToast: false,
174	      });
175	      toast({
176	        title: 'Erro ao carregar matrix de visibilidade',
177	        variant: 'destructive',
178	      });
179	    } finally {
180	      setLoading(false);
181	    }
182	  };
183	
184	  const setores = useMemo(() => {
185	    return ['Todos', ...officialSetoresList];
186	  }, [officialSetoresList]);
187	
188	  const filteredProducts = useMemo(() => {
189	    const term = searchTerm.trim().toLowerCase();
190	    return allProducts.filter((p) => {
191	      const matchesSearch =
192	        !term ||
193	        p.nome.toLowerCase().includes(term) ||
194	        (p.codigo_interno?.toString() || '').includes(term);
195	      const matchesSetor =
196	        setorSelecionado === 'Todos' || p.setor === setorSelecionado;
197	      return matchesSearch && matchesSetor;
198	    });
199	  }, [allProducts, searchTerm, setorSelecionado]);
200	
201	  const groupedProducts = useMemo(() => {
202	    const groups: Record<string, Produto[]> = {};
203	    filteredProducts.forEach((p) => {
204	      if (!groups[p.setor]) groups[p.setor] = [];
205	      groups[p.setor].push(p);
206	    });
207	    return groups;
208	  }, [filteredProducts]);
209	
210	  const toggleCell = (prodId: number, lojaId: number) => {
211	    const key = visKey(prodId, lojaId);
212	    setVisibility((prev) => ({ ...prev, [key]: !prev[key] }));
213	  };
214	
215	  const selectAllForStore = (lojaId: number) => {
216	    setVisibility((prev) => {
217	      const next = { ...prev };
218	      filteredProducts.forEach((p) => {
219	        next[visKey(p.id, lojaId)] = true;
220	      });
221	      return next;
222	    });
223	  };
224	
225	  const deselectAllForStore = (lojaId: number) => {
226	    setVisibility((prev) => {
227	      const next = { ...prev };
228	      filteredProducts.forEach((p) => {
229	        next[visKey(p.id, lojaId)] = false;
230	      });
231	      return next;
232	    });
233	  };
234	
235	  const selectSectorForStore = (setor: string, lojaId: number) => {
236	    setVisibility((prev) => {
237	      const next = { ...prev };
238	      filteredProducts
239	        .filter((p) => p.setor === setor)
240	        .forEach((p) => {
241	          next[visKey(p.id, lojaId)] = true;
242	        });
243	      return next;
244	    });
245	  };
246	
247	  const deselectSectorForStore = (setor: string, lojaId: number) => {
248	    setVisibility((prev) => {
249	      const next = { ...prev };
250	      filteredProducts
251	        .filter((p) => p.setor === setor)
252	        .forEach((p) => {
253	          next[visKey(p.id, lojaId)] = false;
254	        });
255	      return next;
256	    });
257	  };
258	
259	  const hasChanges = useMemo(
260	    () => JSON.stringify(visibility) !== JSON.stringify(initialVisibility),
261	    [visibility, initialVisibility],
262	  );
263	
264	  const changedCount = useMemo(() => {
265	    const keys = new Set([
266	      ...Object.keys(visibility),
267	      ...Object.keys(initialVisibility),
268	    ]);
269	    let count = 0;
270	    keys.forEach((k) => {
271	      if ((visibility[k] ?? false) !== (initialVisibility[k] ?? false)) count++;
272	    });
273	    return count;
274	  }, [visibility, initialVisibility]);
275	
276	  const handleSave = async () => {
277	    setSaving(true);
278	    try {
279	      const keys = new Set([
280	        ...Object.keys(visibility),
281	        ...Object.keys(initialVisibility),
282	      ]);
283	      const upserts: {
284	        produto_master_id: number;
285	        loja_id: number;
286	        ativo: boolean;
287	      }[] = [];
288	
289	      keys.forEach((k) => {
290	        const newVal = visibility[k] ?? false;
291	        const oldVal = initialVisibility[k] ?? false;
292	        if (newVal !== oldVal) {
293	          const [prodId, lojaId] = k.split('_').map(Number);
294	          upserts.push({
295	            produto_master_id: prodId,
296	            loja_id: lojaId,
297	            ativo: newVal,
298	          });
299	        }
300	      });
301	
302	      if (upserts.length === 0) {
303	        toast({ title: 'Nenhuma alteração para salvar' });
304	        setSaving(false);
305	        return;
306	      }
307	
308	      // Chunking para lotes grandes
309	      for (let i = 0; i < upserts.length; i += 100) {
310	        const batch = upserts.slice(i, i + 100);
311	        const { error } = await supabase
312	          .from('produto_loja_visibility' as any)
313	          .upsert(batch as any, { onConflict: 'produto_master_id,loja_id' });
314	        if (error) throw error;
315	      }
316	
317	      setInitialVisibility({ ...visibility });
318	      toast({ title: `${upserts.length} alterações salvas com sucesso!` });
319	    } catch (error) {
320	      handleError(error, {
321	        domain: 'produtos',
322	        operation: 'saveVisibilityMatrix',
323	        showToast: false,
324	      });
325	      toast({
326	        title: 'Erro ao salvar alterações',
327	        variant: 'destructive',
328	      });
329	    } finally {
330	      setSaving(false);
331	    }
332	  };
333	
334	  return (
335	    <div className="space-y-4">
336	      {/* Header / Controls */}
337	      <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 p-4 rounded-3xl shadow-sm">
338	        <div className="flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center">
339	          <div className="flex items-center gap-3">
340	            <Button data-mia-action="on-back"
341	              variant="ghost"
342	              onClick={onBack}
343	              className="gap-2 text-[#57715B] hover:bg-[#57715B]/10 rounded-xl"
344	            >
345	              <ArrowLeft className="h-4 w-4" /> Voltar
346	            </Button>
