import { useEffect, useState } from 'react';
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/shared/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { Button } from '@/shared/ui/button';
import { useSetores } from '../model/useSetores';
import { useToast } from '@/shared/hooks/use-toast';
import { Loader2 } from 'lucide-react';

export interface ProdutoEdit {
  id: number;
  nome: string;
  setor: string;
  unidade_medida: string | null;
}

interface ProdutoSetorUnidadeDialogProps {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  produto: ProdutoEdit | null;
  onSaved?: (id: number, setor: string, unidade: string) => void;
}

const UNIDADES_MEDIDA = [
  'unidade',
  'kg',
  'g',
  'l',
  'ml',
  'm',
  'cm',
  'caixa',
  'fardo',
];
const UNIDADE_LABELS: Record<string, string> = {
  unidade: 'unidade',
  kg: 'kg (Quilograma)',
  g: 'g (Grama)',
  l: 'l (Litro)',
  ml: 'ml (Mililitro)',
  m: 'm (Metro)',
  cm: 'cm (Centímetro)',
  caixa: 'caixa',
  fardo: 'fardo',
};

export function ProdutoSetorUnidadeDialog({
  open,
  onOpenChange,
  produto,
  onSaved,
}: ProdutoSetorUnidadeDialogProps) {
  const { setores: setoresCanonicos, atualizarProdutoSetorUnidade } =
    useSetores();
  const { toast } = useToast();

  const [setor, setSetor] = useState('');
  const [unidade, setUnidade] = useState('unidade');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (produto) {
      const isSetorValido = setoresCanonicos.some((s) => s.nome === produto.setor);
      setSetor(isSetorValido ? produto.setor : '');
      setUnidade(produto.unidade_medida || 'unidade');
    } else {
      setSetor('');
      setUnidade('unidade');
    }
  }, [produto, setoresCanonicos]);

  const handleSave = async () => {
    if (!produto || !setor) return;

    setSaving(true);
    try {
      const result = await atualizarProdutoSetorUnidade(
        produto.id,
        setor,
        unidade,
      );
      if (result.ok) {
        toast({ title: 'Produto atualizado com sucesso!' });
        onSaved?.(produto.id, setor, unidade);
        onOpenChange(false);
      } else {
        toast({
          title: 'Erro ao atualizar',
          description: result.error,
          variant: 'destructive',
        });
      }
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl sm:max-w-[420px]">
        <DialogHeader>
          <DialogTitle>Editar produto</DialogTitle>
          {produto && (
            <p className="text-lg font-semibold text-[#2D362E] dark:text-[#E6DCCF] pt-2">
              {produto.nome}
            </p>
          )}
        </DialogHeader>
        <div className="grid gap-4 py-4">
          <div className="grid grid-cols-4 items-center gap-4">
            <label htmlFor="setor" className="text-right text-sm">
              Setor
            </label>
            <div className="col-span-3">
              <Select value={setor} onValueChange={setSetor}>
                <SelectTrigger
                  id="setor"
                  data-mia-field="edit_setor"
                  className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl"
                >
                  <SelectValue placeholder="Selecione o setor" />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
                  {setoresCanonicos.map((s) => (
                    <SelectItem key={s.nome} value={s.nome}>
                      {s.nome}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div className="grid grid-cols-4 items-center gap-4">
            <label htmlFor="unidade" className="text-right text-sm">
              Unidade
            </label>
            <div className="col-span-3">
              <Select value={unidade} onValueChange={setUnidade}>
                <SelectTrigger
                  id="unidade"
                  data-mia-field="edit_unidade"
                  className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl"
                >
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
                  {UNIDADES_MEDIDA.map((u) => (
                    <SelectItem key={u} value={u}>
                      {UNIDADE_LABELS[u] || u}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="ghost" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button
            data-mia-action="salvar_setor_unidade"
            onClick={handleSave}
            disabled={!setor || saving}
            className="bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl"
          >
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            Salvar
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useEffect, useMemo, useState } from 'react';
import {
  Loader2,
  Save,
  ArrowLeft,
  CheckSquare,
  XSquare,
  Search,
  Layers,
} from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Checkbox } from '@/shared/ui/checkbox';
import { Input } from '@/shared/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { supabase } from '@/integrations/supabase/client';
import { toast } from '@/shared/hooks/use-toast';
import { handleError } from '@/shared/lib/error-handler';
import { useSetores } from '../model/useSetores';
import { SetorManager } from './SetorManager';
import {
  ProdutoSetorUnidadeDialog,
  type ProdutoEdit,
} from './ProdutoSetorUnidadeDialog';

/**
 * Matrix de Visibilidade Produto × Loja.
 *
 * Admin-only. Carrega produtos ativos de `produtos_master` e lojas ativas,
 * cruza com `produto_loja_visibility` e renderiza um grid de checkboxes.
 * Controla quais produtos aparecem na aba Contagem de cada loja.
 *
 * Recuperado do commit 41a96c4 (perdido no refactor FSD). A view
 * `vw_produtos_estoque_lojas` que alimenta a contagem JÁ faz INNER JOIN
 * com esta tabela, então as mudanças refletem direto na contagem.
 */

interface ProductVisibilityMatrixProps {
  onBack: () => void;
}

interface Produto {
  id: number;
  nome: string;
  setor: string;
  codigo_interno: number | null;
  unidade_medida: string | null;
}

interface Loja {
  id: number;
  nome: string;
}

const visKey = (prodId: number, lojaId: number) => `${prodId}_${lojaId}`;

const setorEmoji = (nome: string): string => {
  const n = (nome || '').toLowerCase();
  if (n.includes('camara fria') || n.includes('câmara fria')) return '❄️';
  if (n === 'insumos' || n.includes('estoque insumos')) return '🥄';
  if (n === 'mercearia') return '🛒';
  if (n === 'embalagens') return '📦';
  if (n === 'limpeza') return '🧼';
  if (n === 'natal') return '🎅';
  if (n === 'todos') return '🌎';
  if (n === 'sem setor') return '❓';
  return '🏷️';
};

export function ProductVisibilityMatrix({
  onBack,
}: ProductVisibilityMatrixProps) {
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [allProducts, setAllProducts] = useState<Produto[]>([]);
  const [lojas, setLojas] = useState<Loja[]>([]);
  const [officialSetoresList, setOfficialSetoresList] = useState<string[]>([]);
  const [visibility, setVisibility] = useState<Record<string, boolean>>({});
  const [initialVisibility, setInitialVisibility] = useState<
    Record<string, boolean>
  >({});
  const [searchTerm, setSearchTerm] = useState('');
  const [setorSelecionado, setSetorSelecionado] = useState('Todos');

  const [selectedIds, setSelectedIds] = useState<Set<number>>(new Set());
  const [setorDestino, setSetorDestino] = useState('');
  const [showSetorManager, setShowSetorManager] = useState(false);
  const [editandoProduto, setEditandoProduto] = useState<ProdutoEdit | null>(
    null,
  );
  const [movendoMassa, setMovendoMassa] = useState(false);
  const { setores: setoresCanonicos, moverItensSelecionados } = useSetores();

  useEffect(() => {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const reloadSetores = async () => {
    const { data, error } = await supabase
      .from('setores')
      .select('nome, ativo')
      .eq('ativo', true)
      .order('nome');
    if (!error && data) {
      const officialSetores = (data as any[])
        .map((s: any) => s.nome as string)
        .filter((n: string) => !!n && n.trim() !== '');
      setOfficialSetoresList(officialSetores);
    }
  };

  const loadData = async () => {
    setLoading(true);
    try {
      // 1. Setores oficiais (fonte da verdade — mesma tabela usada na Contagem)
      const { data: setoresData, error: setoresError } = await supabase
        .from('setores')
        .select('nome, ativo')
        .eq('ativo', true)
        .order('nome');
      if (setoresError) throw setoresError;
      const officialSetores = (setoresData || [])
        .map((s: any) => s.nome as string)
        .filter((n: string) => !!n && n.trim() !== '');
      // Map normalizado (UPPERCASE + trim) → nome canônico para match case-insensitive
      const officialMap = new Map<string, string>();
      officialSetores.forEach((n) => {
        officialMap.set(n.trim().toUpperCase(), n);
      });

      // 2. Produtos ativos
      const { data: productsData, error: productsError } = await supabase
        .from('produtos_master')
        .select('id, nome, setor, codigo_interno, ativo, unidade_medida')
        .eq('ativo', true)
        .order('nome');
      if (productsError) throw productsError;

      // 3. Lojas ativas
      const { data: lojasData, error: lojasError } = await supabase
        .from('lojas')
        .select('id, nome')
        .or('ativo.eq.true,ativo.is.null')
        .order('id');
      if (lojasError) throw lojasError;

      // 4. Visibilidade (paginado — pode ultrapassar 1000 linhas)
      const visAll: {
        produto_master_id: number;
        loja_id: number;
        ativo: boolean;
      }[] = [];
      let offset = 0;
      const PAGE = 1000;
      while (true) {
        const { data: batch, error: batchErr } = await supabase
          .from('produto_loja_visibility' as any)
          .select('produto_master_id, loja_id, ativo')
          .range(offset, offset + PAGE - 1);
        if (batchErr) throw batchErr;
        if (!batch || batch.length === 0) break;
        visAll.push(...(batch as any));
        if (batch.length < PAGE) break;
        offset += PAGE;
      }

      // Normaliza setor de cada produto pro nome canônico (case-insensitive).
      // Produtos com setor inválido (NULL, "Todos", etc) recebem 'SEM SETOR' em vez de serem descartados.
      const prods: Produto[] = (productsData || []).map((p: any) => {
        const raw = (p.setor || '').trim();
        const canonical = raw ? officialMap.get(raw.toUpperCase()) : undefined;
        return {
          id: p.id,
          nome: p.nome,
          setor: canonical ?? 'SEM SETOR',
          codigo_interno: p.codigo_interno,
          unidade_medida: p.unidade_medida,
        };
      });

      setAllProducts(prods);
      setOfficialSetoresList(officialSetores);
      setLojas(
        (lojasData || []).map((l: any) => ({ id: l.id, nome: l.nome })),
      );

      const visMap: Record<string, boolean> = {};
      visAll.forEach((v) => {
        visMap[visKey(v.produto_master_id, v.loja_id)] = v.ativo;
      });
      setVisibility(visMap);
      setInitialVisibility({ ...visMap });
    } catch (error) {
      handleError(error, {
        domain: 'produtos',
        operation: 'loadVisibilityMatrix',
        showToast: false,
      });
      toast({
        title: 'Erro ao carregar matrix de visibilidade',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const setores = useMemo(() => {
    const hasOrfaos = allProducts.some((p) => p.setor === 'SEM SETOR');
    return [
      'Todos',
      ...(hasOrfaos ? ['SEM SETOR'] : []),
      ...officialSetoresList,
    ];
  }, [officialSetoresList, allProducts]);

  const filteredProducts = useMemo(() => {
    const term = searchTerm.trim().toLowerCase();
    return allProducts.filter((p) => {
      const matchesSearch =
        !term ||
        p.nome.toLowerCase().includes(term) ||
        (p.codigo_interno?.toString() || '').includes(term);
      const matchesSetor =
        setorSelecionado === 'Todos' || p.setor === setorSelecionado;
      return matchesSearch && matchesSetor;
    });
  }, [allProducts, searchTerm, setorSelecionado]);

  const groupedProducts = useMemo(() => {
    const groups: Record<string, Produto[]> = {};
    filteredProducts.forEach((p) => {
      if (!groups[p.setor]) groups[p.setor] = [];
      groups[p.setor].push(p);
    });
    return groups;
  }, [filteredProducts]);

  const toggleCell = (prodId: number, lojaId: number) => {
    const key = visKey(prodId, lojaId);
    setVisibility((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const selectAllForStore = (lojaId: number) => {
    setVisibility((prev) => {
      const next = { ...prev };
      filteredProducts.forEach((p) => {
        next[visKey(p.id, lojaId)] = true;
      });
      return next;
    });
  };

  const deselectAllForStore = (lojaId: number) => {
    setVisibility((prev) => {
      const next = { ...prev };
      filteredProducts.forEach((p) => {
        next[visKey(p.id, lojaId)] = false;
      });
      return next;
    });
  };

  const selectSectorForStore = (setor: string, lojaId: number) => {
    setVisibility((prev) => {
      const next = { ...prev };
      filteredProducts
        .filter((p) => p.setor === setor)
        .forEach((p) => {
          next[visKey(p.id, lojaId)] = true;
        });
      return next;
    });
  };

  const deselectSectorForStore = (setor: string, lojaId: number) => {
    setVisibility((prev) => {
      const next = { ...prev };
      filteredProducts
        .filter((p) => p.setor === setor)
        .forEach((p) => {
          next[visKey(p.id, lojaId)] = false;
        });
      return next;
    });
  };

  const hasChanges = useMemo(
    () => JSON.stringify(visibility) !== JSON.stringify(initialVisibility),
    [visibility, initialVisibility],
  );

  const changedCount = useMemo(() => {
    const keys = new Set([
      ...Object.keys(visibility),
      ...Object.keys(initialVisibility),
    ]);
    let count = 0;
    keys.forEach((k) => {
      if ((visibility[k] ?? false) !== (initialVisibility[k] ?? false))
        count++;
    });
    return count;
  }, [visibility, initialVisibility]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const keys = new Set([
        ...Object.keys(visibility),
        ...Object.keys(initialVisibility),
      ]);
      const upserts: {
        produto_master_id: number;
        loja_id: number;
        ativo: boolean;
      }[] = [];

      keys.forEach((k) => {
        const newVal = visibility[k] ?? false;
        const oldVal = initialVisibility[k] ?? false;
        if (newVal !== oldVal) {
          const [prodId, lojaId] = k.split('_').map(Number);
          upserts.push({
            produto_master_id: prodId,
            loja_id: lojaId,
            ativo: newVal,
          });
        }
      });

      if (upserts.length === 0) {
        toast({ title: 'Nenhuma alteração para salvar' });
        setSaving(false);
        return;
      }

      // Chunking para lotes grandes
      for (let i = 0; i < upserts.length; i += 100) {
        const batch = upserts.slice(i, i + 100);
        const { error } = await supabase
          .from('produto_loja_visibility' as any)
          .upsert(batch as any, { onConflict: 'produto_master_id,loja_id' });
        if (error) throw error;
      }

      setInitialVisibility({ ...visibility });
      toast({ title: `${upserts.length} alterações salvas com sucesso!` });
    } catch (error) {
      handleError(error, {
        domain: 'produtos',
        operation: 'saveVisibilityMatrix',
        showToast: false,
      });
      toast({
        title: 'Erro ao salvar alterações',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  const handleMoverMassa = async () => {
    if (selectedIds.size === 0 || !setorDestino) return;
    setMovendoMassa(true);
    const r = await moverItensSelecionados([...selectedIds], setorDestino);
    if (r.ok) {
      toast({
        title: `${r.movidos ?? 0} produtos movidos para ${setorDestino}`,
      });
      setAllProducts((prev) =>
        prev.map((p) =>
          selectedIds.has(p.id) ? { ...p, setor: setorDestino } : p,
        ),
      );
      setSelectedIds(new Set());
      setSetorDestino('');
    } else {
      toast({
        title: 'Erro ao mover produtos',
        description: r.error,
        variant: 'destructive',
      });
    }
    setMovendoMassa(false);
  };

  return (
    <div className="space-y-4">
      {/* Header / Controls */}
      <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 p-4 rounded-3xl shadow-sm">
        <div className="flex flex-col xl:flex-row gap-4 justify-between items-start xl:items-center">
          <div className="flex items-center gap-3">
            <Button
              data-mia-action="on-back"
              variant="ghost"
              onClick={onBack}
              className="gap-2 text-[#57715B] hover:bg-[#57715B]/10 rounded-xl"
            >
              <ArrowLeft className="h-4 w-4" /> Voltar
            </Button>
            <div>
              <h2 className="text-xl font-bold text-[#2D362E] dark:text-[#E6DCCF]">
                Gerenciar Visibilidade por Loja
              </h2>
              <p className="text-xs text-muted-foreground">
                {filteredProducts.length} produtos · {lojas.length} lojas
                {changedCount > 0 && (
                  <span className="ml-2 text-amber-600 font-medium">
                    ({changedCount} alterações não salvas)
                  </span>
                )}
              </p>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row gap-2 w-full xl:w-auto">
            <div className="relative flex-1 sm:w-[260px]">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                data-mia-field="search_term"
                placeholder="Buscar por nome ou código..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-9 bg-white/80 dark:bg-zinc-900/80 border-[#57715B]/20 rounded-xl h-10"
              />
            </div>
            <Select value={setorSelecionado} onValueChange={setSetorSelecionado}>
              <SelectTrigger
                data-mia-filter="setor_selecionado"
                className="w-full sm:w-[200px] bg-white/80 dark:bg-zinc-900/80 border-[#57715B]/20 rounded-xl h-10"
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {setores.map((s) => (
                  <SelectItem key={s} value={s}>
                    <span className="mr-2">{setorEmoji(s)}</span>
                    {s}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              data-mia-action="abrir_gerir_setores"
              onClick={() => setShowSetorManager(true)}
              className="bg-white/60 dark:bg-black/20 border border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10 rounded-xl h-10 gap-2 shrink-0"
            >
              <Layers className="h-4 w-4" />
              <span className="hidden sm:inline">Gerenciar Setores</span>
            </Button>
          </div>
        </div>
      </div>

      {/* Matrix */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <div className="flex flex-col items-center gap-3">
            <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
            <p className="text-[#57715B] font-medium">
              Carregando matrix de visibilidade...
            </p>
          </div>
        </div>
      ) : filteredProducts.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground bg-white/60 dark:bg-zinc-900/60 rounded-3xl border border-[#57715B]/10">
          <p className="text-lg font-medium">Nenhum produto encontrado</p>
          <p className="text-sm mt-1">Ajuste os filtros para ver produtos.</p>
        </div>
      ) : (
        <div className="bg-white/60 dark:bg-zinc-900/60 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-3xl shadow-sm overflow-hidden">
          <div className="overflow-auto max-h-[calc(100vh-300px)]">
            <table className="w-full text-sm border-separate border-spacing-0">
              <thead>
                <tr>
                  <th
                    className="sticky left-0 bg-white dark:bg-zinc-900 text-left p-3 font-bold text-[#57715B] dark:text-[#E6DCCF] min-w-[280px] border-b border-[#57715B]/10"
                    style={{ top: 0, zIndex: 30 }}
                  >
                    Produto
                  </th>
                  {lojas.map((loja) => (
                    <th
                      key={loja.id}
                      className="p-3 text-center min-w-[120px] bg-white dark:bg-zinc-900 border-b border-[#57715B]/10 sticky"
                      style={{ top: 0, zIndex: 20 }}
                    >
                      <div className="flex flex-col items-center gap-2">
                        <span className="font-bold text-xs text-[#57715B] dark:text-[#E6DCCF] whitespace-nowrap">
                          {loja.nome.replace('Momma ', '')}
                        </span>
                        <div className="flex items-center gap-1">
                          <button
                            onClick={() => selectAllForStore(loja.id)}
                            className="p-1 rounded hover:bg-green-100 dark:hover:bg-green-900/30 text-green-600 dark:text-green-400 transition-colors"
                            title={`Marcar todos em ${loja.nome}`}
                          >
                            <CheckSquare className="h-3.5 w-3.5" />
                          </button>
                          <button
                            onClick={() => deselectAllForStore(loja.id)}
                            className="p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 dark:text-red-400 transition-colors"
                            title={`Desmarcar todos em ${loja.nome}`}
                          >
                            <XSquare className="h-3.5 w-3.5" />
                          </button>
                        </div>
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {Object.entries(groupedProducts)
                  .sort(([a], [b]) => {
                    if (a === 'SEM SETOR') return -1;
                    if (b === 'SEM SETOR') return 1;
                    return a.localeCompare(b, 'pt-BR');
                  })
                  .map(([setor, prods]) => (
                    <>
                      <tr
                        key={`setor-${setor}`}
                        className="bg-[#57715B]/5 dark:bg-[#57715B]/10"
                      >
                        <td
                          className="sticky left-0 p-2 px-3 bg-[#f8f9fa] dark:bg-[#18181b] border-y border-[#57715B]/10"
                          style={{ zIndex: 15 }}
                        >
                          <div className="flex items-center gap-2">
                            <Checkbox
                              checked={
                                prods.length > 0 &&
                                prods.every((p) => selectedIds.has(p.id))
                              }
                              onCheckedChange={(checked) => {
                                setSelectedIds((prev) => {
                                  const next = new Set(prev);
                                  prods.forEach((p) => {
                                    if (checked) {
                                      next.add(p.id);
                                    } else {
                                      next.delete(p.id);
                                    }
                                  });
                                  return next;
                                });
                              }}
                              aria-label={`Selecionar todos de ${setor}`}
                              className="h-4 w-4 rounded border-[#57715B]/30 data-[state=checked]:bg-[#57715B] data-[state=checked]:border-[#57715B] shrink-0"
                            />
                            <span className="font-bold text-xs uppercase tracking-wider text-[#57715B] dark:text-[#E6DCCF]">
                              {setorEmoji(setor)} {setor} ({prods.length})
                            </span>
                          </div>
                        </td>
                        {lojas.map((loja) => (
                          <td
                            key={loja.id}
                            className="p-1 text-center bg-[#f8f9fa] dark:bg-[#18181b] border-y border-[#57715B]/10"
                          >
                            <div className="flex items-center justify-center gap-1">
                              <button
                                onClick={() =>
                                  selectSectorForStore(setor, loja.id)
                                }
                                className="p-1 rounded hover:bg-green-100 dark:hover:bg-green-900/30 text-green-600 dark:text-green-400 transition-colors"
                                title={`Marcar ${setor} em ${loja.nome}`}
                              >
                                <CheckSquare className="h-3.5 w-3.5" />
                              </button>
                              <button
                                onClick={() =>
                                  deselectSectorForStore(setor, loja.id)
                                }
                                className="p-1 rounded hover:bg-red-100 dark:hover:bg-red-900/30 text-red-500 dark:text-red-400 transition-colors"
                                title={`Desmarcar ${setor} em ${loja.nome}`}
                              >
                                <XSquare className="h-3.5 w-3.5" />
                              </button>
                            </div>
                          </td>
                        ))}
                      </tr>

                      {/* Product rows */}
                      {prods.map((product, idx) => (
                        <tr
                          key={product.id}
                          className={`border-b border-[#57715B]/5 dark:border-white/5 hover:bg-[#57715B]/5 transition-colors ${
                            idx % 2 === 0
                              ? 'bg-white/40 dark:bg-zinc-900/40'
                              : 'bg-white/20 dark:bg-zinc-900/20'
                          }`}
                        >
                          <td className="sticky left-0 bg-inherit backdrop-blur-xl p-3 z-10">
                            <div className="flex items-center gap-2">
                              <Checkbox
                                checked={selectedIds.has(product.id)}
                                onCheckedChange={() => {
                                  setSelectedIds((prev) => {
                                    const next = new Set(prev);
                                    if (next.has(product.id)) {
                                      next.delete(product.id);
                                    } else {
                                      next.add(product.id);
                                    }
                                    return next;
                                  });
                                }}
                                aria-label={`Selecionar ${product.nome}`}
                                className="h-4 w-4 rounded border-[#57715B]/30 data-[state=checked]:bg-[#57715B] data-[state=checked]:border-[#57715B] shrink-0"
                              />
                              <div className="flex flex-col min-w-0">
                                <button
                                  onClick={() =>
                                    setEditandoProduto({
                                      id: product.id,
                                      nome: product.nome,
                                      setor: product.setor,
                                      unidade_medida: product.unidade_medida,
                                    })
                                  }
                                  data-mia-action="abrir_editor_produto"
                                  aria-label={`Editar ${product.nome}`}
                                  className="text-left font-medium text-[#2D362E] dark:text-[#E6DCCF] text-sm leading-tight hover:text-[#57715B] hover:underline transition-colors cursor-pointer truncate max-w-[220px]"
                                >
                                  {product.nome}
                                </button>
                                <span className="text-[10px] text-[#57715B]/60 font-mono">
                                  SKU: {product.codigo_interno ?? '—'}
                                </span>
                              </div>
                            </div>
                          </td>
                          {lojas.map((loja) => {
                            const key = visKey(product.id, loja.id);
                            const isChecked = visibility[key] ?? false;
                            const wasChanged =
                              (initialVisibility[key] ?? false) !== isChecked;
                            return (
                              <td key={loja.id} className="p-3 text-center">
                                <div className="flex justify-center">
                                  <Checkbox
                                    checked={isChecked}
                                    onCheckedChange={() =>
                                      toggleCell(product.id, loja.id)
                                    }
                                    className={`h-5 w-5 rounded transition-all ${
                                      wasChanged
                                        ? 'border-amber-500 data-[state=checked]:bg-amber-500 ring-2 ring-amber-200'
                                        : 'border-[#57715B]/30 data-[state=checked]:bg-[#57715B] data-[state=checked]:border-[#57715B]'
                                    }`}
                                  />
                                </div>
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </>
                  ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Floating Save Button */}
      {hasChanges && (
        <div className="fixed bottom-6 right-6 z-50">
          <Button
            data-mia-action="save"
            onClick={handleSave}
            disabled={saving || loading}
            className="bg-[#57715B] hover:bg-[#57715B]/90 text-white gap-2 shadow-xl shadow-[#57715B]/30 rounded-full px-6 h-12"
          >
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Save className="h-4 w-4" />
            )}
            Salvar {changedCount} alterações
          </Button>
        </div>
      )}

      {/* Floating Bulk Action Bar */}
      {selectedIds.size > 0 && (
        <div className="fixed bottom-6 left-6 z-50 flex items-center gap-3 bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border border-white/40 dark:border-white/10 rounded-2xl shadow-xl px-4 py-3">
          <span className="text-sm font-semibold text-[#2D362E] dark:text-[#E6DCCF] whitespace-nowrap">
            {selectedIds.size} selecionado{selectedIds.size !== 1 ? 's' : ''}
          </span>
          <Select value={setorDestino} onValueChange={setSetorDestino}>
            <SelectTrigger className="w-[160px] bg-white/60 dark:bg-black/20 border-[#57715B]/15 rounded-xl h-9 text-sm">
              <SelectValue placeholder="Mover para..." />
            </SelectTrigger>
            <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-xl">
              {setoresCanonicos.map((s) => (
                <SelectItem
                  key={s.nome}
                  value={s.nome}
                  className="focus:bg-[#57715B]/10 rounded-lg"
                >
                  {s.nome}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button
            data-mia-action="mover_selecionados"
            onClick={handleMoverMassa}
            disabled={!setorDestino || movendoMassa}
            className="bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-3 text-sm gap-1 shrink-0"
          >
            {movendoMassa && <Loader2 className="h-3 w-3 animate-spin" />}
            Mover
          </Button>
          <button
            onClick={() => setSelectedIds(new Set())}
            aria-label="Limpar seleção"
            className="text-muted-foreground hover:text-[#57715B] text-sm underline shrink-0"
          >
            Limpar
          </button>
        </div>
      )}

      <SetorManager
        open={showSetorManager}
        onOpenChange={setShowSetorManager}
        onChanged={reloadSetores}
      />

      <ProdutoSetorUnidadeDialog
        open={!!editandoProduto}
        produto={editandoProduto}
        onOpenChange={(v) => {
          if (!v) setEditandoProduto(null);
        }}
        onSaved={(id, setor, unidade) => {
          setAllProducts((prev) =>
            prev.map((p) =>
              p.id === id ? { ...p, setor, unidade_medida: unidade } : p,
            ),
          );
          setEditandoProduto(null);
        }}
      />
    </div>
  );
}

